#!/usr/bin/perl
# Makes eating-eggs.html, the public copy of the Guide's Eating eggs page (her 2026-11-04 pick "in the room + a link"), from index.html's
# own code, so the two never drift. Run it from the repo root after any change to EATING EGGS, the Meals body or the body drawing:
#   perl .github/scripts/make-eating-eggs-page.pl
# It reads index.html: the IRON and EATING EGGS CSS blocks, the Meals body's figure rules, the EATING EGGS script block, the body drawing
# (PH_BODY_GEOM, phBodySide, phRenAnatomyHtml, the womb), MEALS BODY, and the egg's row and goals. It writes eating-eggs.html: no patient
# data, no sign-in, nothing saved; out of search results (noindex). The patient copy hides the Draft tag and Copy link and opens on Not
# pregnant. Published by .github/workflows/pages.yml.
use strict; use warnings;
sub slurp { open(my $h, "<:raw", $_[0]) or die "cannot read $_[0]\n"; local $/; my $s = <$h>; close $h; $s =~ s/\r\n/\n/g; return $s; }
my $app = slurp("index.html");
sub block { my ($a, $b) = @_; my $i = index($app, $a); die "start not found: $a\n" if $i < 0; die "start found twice: $a\n" if index($app, $a, $i + 1) >= 0;
  my $j = index($app, $b, $i); die "end not found: $b\n" if $j < 0; return substr($app, $i, $j - $i + length($b)); }
my @lines = split /\n/, $app;   # one pass over the lines: a /^...$/m search of the whole 13 MB file is far too slow
sub line { my ($re) = @_; my @m = grep { /^[ \t]*$re/ } @lines; die "want one line for $re, found " . scalar(@m) . "\n" unless @m == 1; return $m[0] . "\n"; }
# from the line that starts it to the first line that ends it (both as they stand in the file)
sub range { my ($from, $to) = @_; my $i = -1; for my $k (0 .. $#lines) { if ($lines[$k] =~ $from) { die "start found twice: $from\n" if $i >= 0; $i = $k; } } die "start not found: $from\n" if $i < 0;
  for my $k ($i + 1 .. $#lines) { return join("\n", @lines[$i .. $k]) . "\n" if $lines[$k] =~ $to; } die "end not found: $to\n"; }
my $fig = join("", map { "$_\n" } grep { /^  #pharmacyPage \.ph-mbd-(?:fig|me|b4|ln|lb)\b/ } @lines);
die "the figure's rules are missing\n" unless length($fig) > 400;
my $css = block("/* ============ IRON TEACHING PAGE", "/* ==== end of IRON TEACHING PAGE ==== */") . "\n"
  . $fig . line(qr/\@media \(prefers-reduced-motion: reduce\) \{ #pharmacyPage \.ph-mbd-fig \.mb-lit/)
  . block("/* ============ EATING EGGS TEACHING PAGE", "/* ==== end of EATING EGGS TEACHING PAGE ==== */") . "\n";
my $mbd = block("  const PH_MBD_COL = {", "  const PH_MBD_FOODC = ["); $mbd =~ s/  const PH_MBD_FOODC = \[\z//;
my $js = line(qr/const phTpReduceMotion = /) . line(qr/const PH_DIET_GOAL0 = /)
  . "  const PH_FOOD = {\n" . line(qr/egg: \["Egg", "eggs",/) . "  };\n"
  . block("  const PH_NUT = [[", "]];") . "\n" . line(qr/const PH_NUT_K = PH_NUT\.map/)
  . range(qr/^  const PH_BODY_GEOM = \(\(\) => \{/, qr/^  \}\)\(\);/) . line(qr/function phBodySide\(view, s\)/)
  . range(qr/^  function phRenAnatomyHtml\(view, female, opts\)/, qr/^  \}$/)
  . range(qr/^  function phIrBabySvg\(\) \{/, qr/^  const phIrWombSvg = /) . range(qr/^  const phIrWombSvg = /, qr/<\/g><\/g>`;$/)
  . $mbd
  . line(qr/let phMbdDrag = null;/) . line(qr/const phMbdDragTo = /) . line(qr/document\.addEventListener\("pointerdown", e => \{ const f = e\.target && e\.target\.closest \? e\.target\.closest\("#pharmacyPage \.ph-mbd-fig\.open"\)/) . line(qr/document\.addEventListener\("pointermove", e => \{ if \(!phMbdDrag\)/) . line(qr/\["pointerup", "pointercancel"\]\.forEach\(t => document\.addEventListener\(t, \(\) => \{ phMbdDrag = null;/)
  . block("  // ---- EATING EGGS: the Guide's Eating eggs tab", "  // ---- end of EATING EGGS ----") . "\n";
# phIrBabySvg's range stops on phIrWombSvg's first line, which the next range starts with: only one copy may stay
$js =~ s/^  const phIrWombSvg = [^\n]*\n(?=  const phIrWombSvg = )//m or die "the womb's first line\n";
my $out = <<"HTML";
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex">
<meta name="theme-color" content="#165C74">
<title>Eating eggs: choline and protein in your body</title>
<link rel="icon" href="icons/favicon-32-v2.png" sizes="32x32">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght\@400;500;600;700&display=swap">
<!-- MADE by .github/scripts/make-eating-eggs-page.pl from index.html's EATING EGGS and MEALS BODY code. Do not edit this file: change those, then re-run it. -->
<style>
html, body { margin: 0; background: #F5F8F9; color: #141F23; }
body { font-family: 'Inter', -apple-system, 'Segoe UI', sans-serif; font-size: 14px; line-height: 1.45; }
* { box-sizing: border-box; }
button { font: inherit; color: inherit; }
.wrap { max-width: 1180px; margin: 0 auto; padding-block: max(12px, env(safe-area-inset-top, 0px)) 28px;
  padding-left: max(14px, env(safe-area-inset-left, 0px)); padding-right: max(14px, env(safe-area-inset-right, 0px)); }
.brand { margin: 2px 2px 10px; font-size: 11px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: #8A6D1A; }
#pharmacyPage { --font-body: 'Inter', -apple-system, 'Segoe UI', sans-serif; --ph-herb: #165C74; --ph-herb-deep: #0B3B4B; --ph-herb-tint: #EDF5F8; --ph-ink: #141F23; --ph-soft: #4A575B; --ph-faint: #626D71;
  --ph-line: #D3DEE2; --ph-white: #FFFFFF; --ph-paper: #F6F9FA; --ph-gold: #D9AE47; --ph-gold-deep: #8A6D1A; --ph-gold-tint: #FFFBE2; --ph-good: #2F7A4F; --ph-zero: #C62828; --ph-low: #E8960C;
  --fs-10: 10px; --fs-10-5: 10.5px; --fs-11: 11px; --fs-11-5: 11.5px; --fs-12: 12px; --fs-12-5: 12.5px; --fs-13: 13px; --fs-13-5: 13.5px; --fs-14: 14px;
  --fs-15: 15px; --fs-16: 16px; --fs-18: 18px; --fs-20: 20px; --fs-22: 22px; --fs-24: 24px; --fs-26: 26px; --fs-28: 28px; color: var(--ph-ink); }
/* the band and its white boxes (the app's shared band rule) */
#pharmacyPage .ph-ir { padding: 12px; border-radius: 10px; background: var(--ph-herb-tint); }
#pharmacyPage .ph-ir .ir-box { padding: 12px 14px 14px; border-radius: 10px; background: var(--ph-white); }
$css
/* the patient's copy: no Draft tag, no Copy link */
#pharmacyPage :is(.ir-draft, [data-ee-link]) { display: none !important; }
</style>
</head>
<body>
<div class="wrap"><div class="brand">Linh Chinese Medicine</div><div id="pharmacyPage"><div id="phGdHost"></div></div></div>
<script>
// the few app helpers the page needs
const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const phAz = (a, b) => String(a).localeCompare(String(b));
const phMacNm = k => ({ ch: "Choline", p: "Protein" })[k] || k;
const phCkCopy = () => {};
const phEgStop = () => {}, phIrStop = () => {};
$js
phMbdView = "body"; phEe.pub = 1; phEe.preg = 0;
document.addEventListener("click", phEeClick);
document.getElementById("phGdHost").innerHTML = phEeHtml();
phEeMount();
</script>
</body>
</html>
HTML
$out =~ s/\r\n/\n/g;   # this script may be checked out with CRLF; the page is LF throughout
open(my $oh, ">:raw", "eating-eggs.html") or die; print $oh $out; close $oh;
print "eating-eggs.html: " . length($out) . " bytes\n";
